import{i as e,r as t,s as n,t as r}from"./app-DuH0mZgh.js";var i=JSON.parse(`{"path":"/29-Deployment_Architecture.html","title":"部署与基础设施架构","lang":"en-US","frontmatter":{},"filePathRelative":"29-Deployment_Architecture.md","git":{"createdTime":1765122408000,"updatedTime":1765122408000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`29-Deployment_Architecture.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="部署与基础设施架构" tabindex="-1"><a class="header-anchor" href="#部署与基础设施架构"><span>部署与基础设施架构</span></a></h1><blockquote><p>目的：详细描述 Apollo MMO 各服务在生产环境的部署拓扑、调度方式、配置中心、CI/CD 结构，以及多环境隔离方案，确保设计能够顺利落地。</p></blockquote><h2 id="_1-环境划分" tabindex="-1"><a class="header-anchor" href="#_1-环境划分"><span>1. 环境划分</span></a></h2><table><thead><tr><th>环境</th><th>用途</th><th>规模</th><th>特点</th></tr></thead><tbody><tr><td>Dev</td><td>开发自测</td><td>单机/小集群</td><td>快速迭代，允许调试</td></tr><tr><td>Test</td><td>集成测试</td><td>1-2 套</td><td>自动化 IT/QA</td></tr><tr><td>Staging</td><td>灰度/压测</td><td>与 Prod 等规模</td><td>全量服务，模拟真实数据</td></tr><tr><td>Prod</td><td>线上</td><td>多 Region/Zone</td><td>高可用、容灾</td></tr></tbody></table><p>每个环境采用独立配置、数据库、Redis；Prod 使用多个 Region，Region 内含多个可用区。</p><h2 id="_2-基础设施" tabindex="-1"><a class="header-anchor" href="#_2-基础设施"><span>2. 基础设施</span></a></h2><h3 id="_2-1-调度-编排" tabindex="-1"><a class="header-anchor" href="#_2-1-调度-编排"><span>2.1 调度/编排</span></a></h3><ul><li>推荐使用 Kubernetes（AKS/EKS/自建）或 HashiCorp Nomad。关键服务（Gate/World/Zone/AOI/DataProxy/LogAgent等）以容器形式运行。</li><li>使用 Helm/Terraform 管理部署。每个服务有独立 Helm chart，包含 ConfigMap/Secrets/Service/StatefulSet。</li><li>对于高性能或需裸金属（如数据库、Battle Service），可使用专用节点池。</li></ul><h3 id="_2-2-服务治理" tabindex="-1"><a class="header-anchor" href="#_2-2-服务治理"><span>2.2 服务治理</span></a></h3><ul><li>Consul/Etcd 作为服务发现与配置中心。</li><li>Consul Template/Envoy Sidecar 实现服务发现 + mTLS。</li><li>使用 HashiCorp Vault 或 KMS 管理密钥/证书，服务启动时动态拉取。</li></ul><h3 id="_2-3-网络拓扑" tabindex="-1"><a class="header-anchor" href="#_2-3-网络拓扑"><span>2.3 网络拓扑</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Internet -&gt; (CDN/Anti-DDoS) -&gt; L4 Load Balancer -&gt; GateServer Pods</span>
<span class="line">                                              ↘ 管理入口 (Ops API)</span>
<span class="line">GateServer -&gt; WorldServer -&gt; Zone/AOI/DataProxy (内部 VPC)</span>
<span class="line">Internal Services -&gt; DB/Redis/Kafka (私网，仅白名单访问)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>使用 VPC + 子网隔离：Public 子网（仅 LB）、Private 子网（应用）、Data 子网（DB/Kafka）。</li><li>安全组限制访问；所有内部通信走 mTLS。</li></ul><h2 id="_3-服务部署拓扑" tabindex="-1"><a class="header-anchor" href="#_3-服务部署拓扑"><span>3. 服务部署拓扑</span></a></h2><table><thead><tr><th>服务</th><th>部署模式</th><th>容器/实例数</th><th>备注</th></tr></thead><tbody><tr><td>GateServer</td><td>Deployment (无状态)</td><td>按并发扩缩</td><td>NodePort/LB 暴露</td></tr><tr><td>WorldServer</td><td>StatefulSet (少量)</td><td>2-3</td><td>需持有全局状态</td></tr><tr><td>Scene Orchestrator</td><td>Deployment</td><td>2+</td><td>可横向扩展</td></tr><tr><td>ZoneServer</td><td>StatefulSet/Deployment</td><td>按地图/实例数</td><td>Pod 内运行多 Zone 线程</td></tr><tr><td>AOI Service</td><td>StatefulSet</td><td>Shard 数量决定</td><td>需固定 Pod/IP</td></tr><tr><td>Battle Service</td><td>StatefulSet</td><td>依据场景</td><td>可有 GPU/特定硬件</td></tr><tr><td>DataProxy</td><td>Deployment</td><td>2N</td><td>支持水平扩容</td></tr><tr><td>Redis/MySQL</td><td>运营商托管或自建 StatefulSet</td><td>集群模式</td><td>建议托管版（Aurora/MySQL Cluster）</td></tr><tr><td>Kafka/ClickHouse</td><td>StatefulSet</td><td>3+</td><td>备份/监控</td></tr><tr><td>Social Services</td><td>Deployment</td><td>2+</td><td>无状态</td></tr><tr><td>LogAgent</td><td>DaemonSet</td><td>1/节点</td><td>收集日志</td></tr></tbody></table><h2 id="_4-配置与-secrets" tabindex="-1"><a class="header-anchor" href="#_4-配置与-secrets"><span>4. 配置与 Secrets</span></a></h2><h3 id="_4-1-配置管理" tabindex="-1"><a class="header-anchor" href="#_4-1-配置管理"><span>4.1 配置管理</span></a></h3><ul><li>结构：<code>config/{env}/{service}.yaml</code> + ConfigMap。</li><li>支持热加载的服务（NetCore、AOI、DataProxy）从 ConfigMap + Consul 动态拉取。</li><li>对敏感配置（DB 密码、TLS 证书）使用 Vault + Secret 注入。</li></ul><h3 id="_4-2-配置升级" tabindex="-1"><a class="header-anchor" href="#_4-2-配置升级"><span>4.2 配置升级</span></a></h3><ul><li>CI Pipeline 检查配置格式，部署时通过 Helm 冻结。</li><li>使用 Feature Flag/Config Toggle 控制灰度。</li></ul><h2 id="_5-ci-cd-流程" tabindex="-1"><a class="header-anchor" href="#_5-ci-cd-流程"><span>5. CI/CD 流程</span></a></h2><h3 id="_5-1-pipeline-步骤" tabindex="-1"><a class="header-anchor" href="#_5-1-pipeline-步骤"><span>5.1 Pipeline 步骤</span></a></h3><ol><li><strong>源码提交</strong> -&gt; 触发 CI（Lint/UT/Build）。</li><li>生成容器镜像 (Docker) + SBOM。</li><li>推送到镜像仓库。</li><li>自动部署到 Test 环境，运行集成测试。</li><li>人工审批/自动 Gate -&gt; 部署 Staging。</li><li>压测/灰度 -&gt; 通过后自动部署 Prod（滚动/蓝绿/金丝雀）。</li></ol><p>工具选择：GitHub Actions/GitLab CI/Jenkins + ArgoCD/Fleet 进行 GitOps。</p><h3 id="_5-2-发布策略" tabindex="-1"><a class="header-anchor" href="#_5-2-发布策略"><span>5.2 发布策略</span></a></h3><ul><li>采用滚动更新和金丝雀发布： <ol><li>Staging 验证。</li><li>Prod 小比例流量（金丝雀）监控指标（RTT、错误）。</li><li>成功后滚动更新全部实例。</li></ol></li><li>关键服务（Gate/World/DataProxy）支持回滚（保留前版本镜像/配置）。</li></ul><h2 id="_6-监控与日志-与-docs-20-关联" tabindex="-1"><a class="header-anchor" href="#_6-监控与日志-与-docs-20-关联"><span>6. 监控与日志（与 <code>docs/20</code> 关联）</span></a></h2><ul><li>每个服务暴露 Prometheus <code>/metrics</code>。</li><li>日志通过 LogAgent -&gt; FluentBit -&gt; ELK。</li><li>Trace 使用 OpenTelemetry Collector，导出至 Jaeger/Tempo。</li><li>告警配置在 Grafana Alert/PagerDuty。</li></ul><h2 id="_7-容灾与备份" tabindex="-1"><a class="header-anchor" href="#_7-容灾与备份"><span>7. 容灾与备份</span></a></h2><ul><li>Prod 多 Region：主 Region + 异地热备，使用数据库双写或半同步复制。</li><li>Kafka/Redis/MySQL 均需跨 Region 备份；ClickHouse 使用复制表。</li><li>每日备份存储到对象存储（加密）；定期执行恢复演练。</li></ul><h2 id="_8-资源管理" tabindex="-1"><a class="header-anchor" href="#_8-资源管理"><span>8. 资源管理</span></a></h2><ul><li>Node 池分类：<code>public</code>（网关）、<code>logic</code>（Zone/AOI/Battle）、<code>data</code>（DB/Kafka）、<code>utility</code>（LogAgent/CI）。</li><li>使用自动扩缩（HPA/Cluster Autoscaler）调节 Gate/Zone 等无状态服务。</li><li>Battle Service/AOI 需要保证 CPU/内存绑定，可用 Dedicated Node Pool + CPU pin。</li></ul><h2 id="_9-安全" tabindex="-1"><a class="header-anchor" href="#_9-安全"><span>9. 安全</span></a></h2><ul><li>所有 Pod 运行在非 root 用户，启用 PSP/OPA 限制。</li><li>使用 Istio/Linkerd（可选）提供 mTLS、策略、观测。</li><li>可通过 WAF/Cloud Armor/Shield 保护入口。</li></ul><h2 id="_10-roadmap" tabindex="-1"><a class="header-anchor" href="#_10-roadmap"><span>10. Roadmap</span></a></h2><ol><li>搭建 Dev/Test K8s 集群，配置 CI/CD Pipeline。</li><li>实现 Helm/ArgoCD 部署流程，覆盖 Gate/World/DataProxy 等服务。</li><li>接入 Consul/Vault，统一服务发现和 secrets。</li><li>建立监控/日志/追踪栈，配合 <code>docs/20</code>。</li><li>完成 Staging/Prod 多 Region 架构，执行容灾演练。</li></ol><hr><p>该部署架构文档为后续基础设施实施提供蓝图，确保服务器设计能在生产环境稳定运行。***</p>`,38)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};